async function loadGitHubComments(e){const{repo:s,issue:a,hiddenIds:l}=e.dataset,r=new Set(l.split(",")),n=e.querySelector("[data-comment-status]"),c=e.querySelector("[data-comment-list]"),i=document.createDocumentFragment(),t=new URL(`https://api.github.com/repos/${s}/issues/${a}/comments`);t.searchParams.set("per_page","100");let o=0;n.textContent="正在加载评论…";try{for(let n=1;;n+=1){t.searchParams.set("page",String(n));const e=await fetch(t,{headers:{Accept:"application/vnd.github+json"}});if(!e.ok)throw new Error(`GitHub API: ${e.status}`);const c=await e.json();for(const e of c){if(r.has(String(e.id)))continue;const l=document.createElement("article"),n=document.createElement("a"),t=document.createElement("p");n.href=`https://github.com/${s}/issues/${a}#issuecomment-${e.id}`,n.textContent=e.user?.login??"GitHub 用户",t.textContent=e.body,t.style.whiteSpace="pre-wrap",t.style.overflowWrap="anywhere",l.append(n,t),i.append(l),o+=1}if(!e.headers.get("Link")?.includes('rel="next"'))break}c.replaceChildren(i),n.textContent=o?"":"暂无评论。"}catch{n.textContent="暂时无法加载评论，可以前往 GitHub 查看。"}}document.querySelectorAll("[data-github-comments]").forEach(loadGitHubComments)